package controller;
import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.scene.layout.FlowPane;import model.*;import service.*;import java.time.Duration;
public final class ResultController {@FXML private Label headline,score,accuracy,time,stars;@FXML private FlowPane achievements;
 @FXML public void initialize(){Player p=GameManager.getInstance().getPlayer();headline.setText(p.getLives()>0?"LABORATORY UNLOCKED":"MISSION DEBRIEF");score.setText(String.valueOf(p.getScore()));accuracy.setText("%.0f%%".formatted(p.getAccuracy()));Duration d=p.getTimePlayed();time.setText("%02d:%02d".formatted(d.toMinutes(),d.toSecondsPart()));int count=ScoreManager.stars(p.getScore(),180);stars.setText("★".repeat(count)+"☆".repeat(5-count));p.getAchievements().forEach(a->{Label badge=new Label("◆  "+a.title());badge.getStyleClass().add("achievement-badge");achievements.getChildren().add(badge);});}
 @FXML private void replay(){GameManager.getInstance().newGame(GameManager.getInstance().getPlayer().getName());SceneManager.switchScene("Instruction.fxml");}@FXML private void review(){Alert a=new Alert(Alert.AlertType.INFORMATION,QuestionLoader.load().stream().map(q->"• "+q.prompt()+"\n  "+q.explanation()).reduce("",(x,y)->x+y+"\n\n"),ButtonType.OK);a.setHeaderText("Research Notes");a.initOwner(SceneManager.getStage());a.showAndWait();}@FXML private void menu(){SceneManager.switchScene("MainMenu.fxml");}@FXML private void exit(){SceneManager.getStage().close();}}
